/**
 * Validates JSON input from stdin.
 * Exits with code 0 for valid JSON, code 1 for invalid JSON.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

/**
 * Validate a string as JSON.
 */
export function validateJson(input: string): ValidationResult {
  if (input.trim() === "") {
    return { valid: false, error: "Empty input" };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (e) {
    const message = e instanceof Error ? e.message : "Unknown error";
    return { valid: false, error: message };
  }
}

if (import.meta.main) {
  const input = await Bun.stdin.text();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    process.exit(1);
  }
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("returns valid for a JSON object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for a JSON array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for a JSON primitive", () => {
    expect(validateJson('"hello"').valid).toBe(true);
    expect(validateJson("42").valid).toBe(true);
    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("null").valid).toBe(true);
  });

  test("returns invalid with error for malformed JSON", () => {
    const result = validateJson("{not json}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid with error for empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("returns invalid with error for whitespace-only input", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });
});

