        "new_string": "import { describe, expect, test } from \"bun:test\";\nimport { greet, add, greetWithTime } from \"./utils\";\n\ndescribe(\"utils\", () => {\n  test(\"greet returns greeting message\", () => {\n    expect(greet(\"Alice\")).toBe(\"Hello, Alice!\");\n  });\n\n  test(\"add returns sum of two numbers\", () => {\n    expect(add(2, 3)).toBe(5);\n  });\n\n  describe(\"greetWithTime\", () => {\n    test(\"returns morning greeting before noon\", () => {\n      expect(greetWithTime(\"Alice\", 8)).toBe(\"Good morning, Alice!\");\n    });\n\n    test(\"returns morning greeting at midnight\", () => {\n      expect(greetWithTime(\"Bob\", 0)).toBe(\"Good morning, Bob!\");\n    });\n\n    test(\"returns afternoon greeting from noon to before 6pm\", () => {\n      expect(greetWithTime(\"Carol\", 12)).toBe(\"Good afternoon, Carol!\");\n    });\n\n    test(\"returns evening greeting from 6pm onward\", () => {\n      expect(greetWithTime(\"Dave\", 18)).toBe(\"Good evening, Dave!\");\n    });\n\n    test(\"returns evening greeting at 11pm\", () => {\n      expect(greetWithTime(\"Eve\", 23)).toBe(\"Good evening, Eve!\");\n    });\n\n    test(\"throws for invalid hour below range\", () => {\n      expect(() => greetWithTime(\"Test\", -1)).toThrow(\"Hour must be between 0 and 23\");\n    });\n\n    test(\"throws for invalid hour above range\", () => {\n      expect(() => greetWithTime(\"Test\", 24)).toThrow(\"Hour must be between 0 and 23\");\n    });\n  });\n});"
