        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJson } from \"./validate-json\";\n\ndescribe(\"validateJson\", () => {\n  describe(\"valid JSON\", () => {\n    test(\"empty object\", () => {\n      expect(validateJson(\"{}\")).toEqual({ valid: true });\n    });\n\n    test(\"empty array\", () => {\n      expect(validateJson(\"[]\")).toEqual({ valid: true });\n    });\n\n    test(\"string value\", () => {\n      expect(validateJson('\"hello\"')).toEqual({ valid: true });\n    });\n\n    test(\"number values\", () => {\n      expect(validateJson(\"42\")).toEqual({ valid: true });\n      expect(validateJson(\"-1\")).toEqual({ valid: true });\n      expect(validateJson(\"3.14\")).toEqual({ valid: true });\n      expect(validateJson(\"1e10\")).toEqual({ valid: true });\n      expect(validateJson(\"1.5E-3\")).toEqual({ valid: true });\n      expect(validateJson(\"0\")).toEqual({ valid: true });\n    });\n\n    test(\"boolean and null\", () => {\n      expect(validateJson(\"true\")).toEqual({ valid: true });\n      expect(validateJson(\"false\")).toEqual({ valid: true });\n      expect(validateJson(\"null\")).toEqual({ valid: true });\n    });\n\n    test(\"nested object\", () => {\n      const json = '{\"name\":\"test\",\"value\":{\"nested\":true},\"list\":[1,2,3]}';\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"nested arrays\", () => {\n      const json = \"[[1,[2,[3]]],[4,5]]\";\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"whitespace around values\", () => {\n      const json = '  {  \"key\"  :  \"value\"  }  ';\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"string with escape sequences\", () => {\n      const json = '{\"msg\":\"line1\\\\nline2\\\\ttab\\\\\\\\\\\\\"quote\\\\/slash\"}';\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"Buffer input\", () => {\n      const buf = Buffer.from('{\"valid\":true}');\n      expect(validateJson(buf)).toEqual({ valid: true });\n    });\n  });\n\n  describe(\"syntax errors\", () => {\n    test(\"empty input\", () => {\n      const result = validateJson(\"\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Empty input\");\n    });\n\n    test(\"trailing comma in object\", () => {\n      const result = validateJson('{\"a\":1,}');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"trailing comma in array\", () => {\n      const result = validateJson(\"[1,2,]\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"missing closing brace\", () => {\n      const result = validateJson('{\"key\":\"value\"');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"missing closing bracket\", () => {\n      const result = validateJson(\"[1,2,3\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"extra content after value\", () => {\n      const result = validateJson('{\"a\":1} extra');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unexpected content\");\n    });\n\n    test(\"invalid escape in string\", () => {\n      const result = validateJson('\"bad\\\\x\"');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Invalid escape\");\n    });\n\n    test(\"unterminated string\", () => {\n      const result = validateJson('\"unterminated');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unterminated string\");\n    });\n\n    test(\"leading zeros in number\", () => {\n      const result = validateJson(\"01\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"incomplete unicode escape\", () => {\n      const result = validateJson('\"\\\\u00\"');\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"unquoted property name\", () => {\n      const result = validateJson(\"{key:1}\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"single quotes\", () => {\n      const result = validateJson(\"{'key':'value'}\");\n      expect(result.valid).toBe(false);\n    });\n  });\n\n  describe(\"depth limits\", () => {\n    test(\"respects maxDepth option\", () => {\n      const deepJson = \"[\".repeat(5) + \"1\" + \"]\".repeat(5);\n      const result = validateJson(deepJson, { maxDepth: 3 });\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Maximum depth\");\n    });\n\n    test(\"allows depth within limit\", () => {\n      const json = \"[\".repeat(5) + \"1\" + \"]\".repeat(5);\n      const result = validateJson(json, { maxDepth: 10 });\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"counts object depth\", () => {\n      const json = '{\"a\":{\"b\":{\"c\":1}}}';\n      const result = validateJson(json, { maxDepth: 2 });\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Maximum depth\");\n    });\n  });\n\n  describe(\"size limits\", () => {\n    test(\"rejects input exceeding maxSize\", () => {\n      const json = '{\"data\":\"' + \"x\".repeat(200) + '\"}';\n      const result = validateJson(json, { maxSize: 50 });\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"exceeds maximum\");\n    });\n\n    test(\"allows input within maxSize\", () => {\n      const json = '{\"ok\":true}';\n      const result = validateJson(json, { maxSize: 1024 });\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"unicode edge cases\", () => {\n    test(\"valid unicode escape sequences\", () => {\n      const json = '\"\\\\u0048\\\\u0065\\\\u006C\\\\u006C\\\\u006F\"';\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"multibyte unicode characters\", () => {\n      const json = '{\"emoji\":\"\\\\u2603\",\"text\":\"cafe\\\\u0301\"}';\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"raw unicode in strings\", () => {\n      const json = JSON.stringify({ greeting: \"\\u3053\\u3093\\u306B\\u3061\\u306F\" });\n      expect(validateJson(json)).toEqual({ valid: true });\n    });\n\n    test(\"invalid unicode escape\", () => {\n      const result = validateJson('\"\\\\uGGGG\"');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"unicode escape\");\n    });\n  });\n\n  describe(\"empty and whitespace inputs\", () => {\n    test(\"whitespace-only input\", () => {\n      const result = validateJson(\"   \\n\\t  \");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"single space\", () => {\n      const result = validateJson(\" \");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"newlines only\", () => {\n      const result = validateJson(\"\\n\\n\\n\");\n      expect(result.valid).toBe(false);\n    });\n  });\n});\n\ndescribe(\"performance benchmark\", () => {\n  test(\"validates 1MB+ JSON payload under 500ms\", () => {\n    const entries: string[] = [];\n    const targetSize = 1024 * 1024; // 1MB\n    let currentSize = 0;\n    let index = 0;\n\n    while (currentSize < targetSize) {\n      const entry = `\"key_${index}\":{\"value\":${index},\"name\":\"item_${index}\",\"active\":true,\"tags\":[\"a\",\"b\",\"c\"]}`;\n      entries.push(entry);\n      currentSize += entry.length;\n      index++;\n    }\n\n    const largeJson = \"{\" + entries.join(\",\") + \"}\";\n    expect(largeJson.length).toBeGreaterThan(targetSize);\n\n    const start = performance.now();\n    const result = validateJson(largeJson);\n    const elapsed = performance.now() - start;\n\n    expect(result.valid).toBe(true);\n    expect(elapsed).toBeLessThan(500);\n  });\n});\n"
