        "content": "/**\n * High-performance single-pass JSON validator using character scanning.\n * Supports configurable depth limits and max size constraints.\n */\n\nexport interface ValidationOptions {\n  maxDepth?: number;\n  maxSize?: number;\n}\n\nexport interface ValidationResult {\n  valid: boolean;\n  error?: string;\n  position?: number;\n}\n\nconst CHAR_SPACE = 0x20;\nconst CHAR_TAB = 0x09;\nconst CHAR_NEWLINE = 0x0a;\nconst CHAR_RETURN = 0x0d;\nconst CHAR_QUOTE = 0x22;\nconst CHAR_BACKSLASH = 0x5c;\nconst CHAR_SLASH = 0x2f;\nconst CHAR_OPEN_BRACE = 0x7b;\nconst CHAR_CLOSE_BRACE = 0x7d;\nconst CHAR_OPEN_BRACKET = 0x5b;\nconst CHAR_CLOSE_BRACKET = 0x5d;\nconst CHAR_COLON = 0x3a;\nconst CHAR_COMMA = 0x2c;\nconst CHAR_MINUS = 0x2d;\nconst CHAR_PLUS = 0x2b;\nconst CHAR_DOT = 0x2e;\nconst CHAR_0 = 0x30;\nconst CHAR_9 = 0x39;\nconst CHAR_a = 0x61;\nconst CHAR_b = 0x62;\nconst CHAR_e = 0x65;\nconst CHAR_E = 0x45;\nconst CHAR_f = 0x66;\nconst CHAR_n = 0x6e;\nconst CHAR_r = 0x72;\nconst CHAR_t = 0x74;\nconst CHAR_u = 0x75;\n\nconst DEFAULT_MAX_DEPTH = 512;\nconst DEFAULT_MAX_SIZE = 100 * 1024 * 1024; // 100MB\n\n/**\n * Validate a JSON string using single-pass character scanning.\n * Returns a result indicating validity and error details if invalid.\n */\nexport function validateJson(\n  input: string | Buffer,\n  options?: ValidationOptions,\n): ValidationResult {\n  const maxDepth = options?.maxDepth ?? DEFAULT_MAX_DEPTH;\n  const maxSize = options?.maxSize ?? DEFAULT_MAX_SIZE;\n\n  const str = typeof input === \"string\" ? input : input.toString(\"utf-8\");\n  const len = str.length;\n\n  if (len === 0) {\n    return { valid: false, error: \"Empty input\", position: 0 };\n  }\n\n  const byteSize = typeof input === \"string\" ? Buffer.byteLength(input, \"utf-8\") : input.length;\n  if (byteSize > maxSize) {\n    return {\n      valid: false,\n      error: `Input size ${byteSize} exceeds maximum ${maxSize} bytes`,\n      position: 0,\n    };\n  }\n\n  let pos = 0;\n  let depth = 0;\n\n  function error(message: string): ValidationResult {\n    return { valid: false, error: message, position: pos };\n  }\n\n  function skipWhitespace(): void {\n    while (pos < len) {\n      const ch = str.charCodeAt(pos);\n      if (\n        ch === CHAR_SPACE ||\n        ch === CHAR_TAB ||\n        ch === CHAR_NEWLINE ||\n        ch === CHAR_RETURN\n      ) {\n        pos++;\n      } else {\n        break;\n      }\n    }\n  }\n\n  function parseString(): ValidationResult | null {\n    if (str.charCodeAt(pos) !== CHAR_QUOTE) {\n      return error(`Expected '\"' at position ${pos}`);\n    }\n    pos++; // skip opening quote\n\n    while (pos < len) {\n      const ch = str.charCodeAt(pos);\n\n      if (ch === CHAR_BACKSLASH) {\n        pos++;\n        if (pos >= len) {\n          return error(`Unexpected end of input in string escape at position ${pos}`);\n        }\n        const esc = str.charCodeAt(pos);\n        if (\n          esc === CHAR_QUOTE ||\n          esc === CHAR_BACKSLASH ||\n          esc === CHAR_SLASH ||\n          esc === CHAR_b ||\n          esc === CHAR_f ||\n          esc === CHAR_n ||\n          esc === CHAR_r ||\n          esc === CHAR_t\n        ) {\n          pos++;\n        } else if (esc === CHAR_u) {\n          pos++;\n          for (let i = 0; i < 4; i++) {\n            if (pos >= len) {\n              return error(`Unexpected end of input in unicode escape at position ${pos}`);\n            }\n            const hex = str.charCodeAt(pos);\n            if (\n              (hex >= CHAR_0 && hex <= CHAR_9) ||\n              (hex >= 0x41 && hex <= 0x46) || // A-F\n              (hex >= 0x61 && hex <= 0x66)    // a-f\n            ) {\n              pos++;\n            } else {\n              return error(`Invalid unicode escape character at position ${pos}`);\n            }\n          }\n        } else {\n          return error(`Invalid escape character '${str[pos]}' at position ${pos}`);\n        }\n      } else if (ch === CHAR_QUOTE) {\n        pos++; // skip closing quote\n        return null; // success\n      } else if (ch < 0x20) {\n        return error(`Invalid control character in string at position ${pos}`);\n      } else {\n        pos++;\n      }\n    }\n\n    return error(`Unterminated string starting at position ${pos}`);\n  }\n\n  function parseNumber(): ValidationResult | null {\n    const start = pos;\n\n    // Optional minus\n    if (str.charCodeAt(pos) === CHAR_MINUS) {\n      pos++;\n    }\n\n    if (pos >= len) {\n      return error(`Unexpected end of input in number at position ${pos}`);\n    }\n\n    // Integer part\n    if (str.charCodeAt(pos) === CHAR_0) {\n      pos++;\n    } else if (str.charCodeAt(pos) >= 0x31 && str.charCodeAt(pos) <= CHAR_9) {\n      pos++;\n      while (pos < len && str.charCodeAt(pos) >= CHAR_0 && str.charCodeAt(pos) <= CHAR_9) {\n        pos++;\n      }\n    } else {\n      return error(`Invalid number at position ${start}`);\n    }\n\n    // Decimal part\n    if (pos < len && str.charCodeAt(pos) === CHAR_DOT) {\n      pos++;\n      if (pos >= len || str.charCodeAt(pos) < CHAR_0 || str.charCodeAt(pos) > CHAR_9) {\n        return error(`Invalid number: expected digit after decimal point at position ${pos}`);\n      }\n      while (pos < len && str.charCodeAt(pos) >= CHAR_0 && str.charCodeAt(pos) <= CHAR_9) {\n        pos++;\n      }\n    }\n\n    // Exponent part\n    if (pos < len && (str.charCodeAt(pos) === CHAR_e || str.charCodeAt(pos) === CHAR_E)) {\n      pos++;\n      if (pos < len && (str.charCodeAt(pos) === CHAR_PLUS || str.charCodeAt(pos) === CHAR_MINUS)) {\n        pos++;\n      }\n      if (pos >= len || str.charCodeAt(pos) < CHAR_0 || str.charCodeAt(pos) > CHAR_9) {\n        return error(`Invalid number: expected digit in exponent at position ${pos}`);\n      }\n      while (pos < len && str.charCodeAt(pos) >= CHAR_0 && str.charCodeAt(pos) <= CHAR_9) {\n        pos++;\n      }\n    }\n\n    return null; // success\n  }\n\n  function parseKeyword(expected: string): ValidationResult | null {\n    for (let i = 0; i < expected.length; i++) {\n      if (pos >= len || str[pos] !== expected[i]) {\n        return error(`Expected '${expected}' at position ${pos - i}`);\n      }\n      pos++;\n    }\n    return null;\n  }\n\n  function parseValue(): ValidationResult | null {\n    skipWhitespace();\n\n    if (pos >= len) {\n      return error(`Unexpected end of input at position ${pos}`);\n    }\n\n    const ch = str.charCodeAt(pos);\n\n    if (ch === CHAR_OPEN_BRACE) {\n      return parseObject();\n    }\n    if (ch === CHAR_OPEN_BRACKET) {\n      return parseArray();\n    }\n    if (ch === CHAR_QUOTE) {\n      return parseString();\n    }\n    if (ch === CHAR_MINUS || (ch >= CHAR_0 && ch <= CHAR_9)) {\n      return parseNumber();\n    }\n    if (ch === CHAR_t) {\n      return parseKeyword(\"true\");\n    }\n    if (ch === CHAR_f) {\n      return parseKeyword(\"false\");\n    }\n    if (ch === CHAR_n) {\n      return parseKeyword(\"null\");\n    }\n\n    return error(`Unexpected character '${str[pos]}' at position ${pos}`);\n  }\n\n  function parseObject(): ValidationResult | null {\n    pos++; // skip '{'\n    depth++;\n\n    if (depth > maxDepth) {\n      return error(`Maximum depth of ${maxDepth} exceeded at position ${pos}`);\n    }\n\n    skipWhitespace();\n\n    if (pos < len && str.charCodeAt(pos) === CHAR_CLOSE_BRACE) {\n      pos++;\n      depth--;\n      return null;\n    }\n\n    while (true) {\n      skipWhitespace();\n\n      if (pos >= len) {\n        return error(`Unexpected end of input in object at position ${pos}`);\n      }\n\n      if (str.charCodeAt(pos) !== CHAR_QUOTE) {\n        return error(`Expected property name in object at position ${pos}`);\n      }\n\n      const strErr = parseString();\n      if (strErr) return strErr;\n\n      skipWhitespace();\n\n      if (pos >= len || str.charCodeAt(pos) !== CHAR_COLON) {\n        return error(`Expected ':' after property name at position ${pos}`);\n      }\n      pos++; // skip ':'\n\n      const valErr = parseValue();\n      if (valErr) return valErr;\n\n      skipWhitespace();\n\n      if (pos >= len) {\n        return error(`Unexpected end of input in object at position ${pos}`);\n      }\n\n      if (str.charCodeAt(pos) === CHAR_CLOSE_BRACE) {\n        pos++;\n        depth--;\n        return null;\n      }\n\n      if (str.charCodeAt(pos) !== CHAR_COMMA) {\n        return error(`Expected ',' or '}' in object at position ${pos}`);\n      }\n      pos++; // skip ','\n    }\n  }\n\n  function parseArray(): ValidationResult | null {\n    pos++; // skip '['\n    depth++;\n\n    if (depth > maxDepth) {\n      return error(`Maximum depth of ${maxDepth} exceeded at position ${pos}`);\n    }\n\n    skipWhitespace();\n\n    if (pos < len && str.charCodeAt(pos) === CHAR_CLOSE_BRACKET) {\n      pos++;\n      depth--;\n      return null;\n    }\n\n    while (true) {\n      const valErr = parseValue();\n      if (valErr) return valErr;\n\n      skipWhitespace();\n\n      if (pos >= len) {\n        return error(`Unexpected end of input in array at position ${pos}`);\n      }\n\n      if (str.charCodeAt(pos) === CHAR_CLOSE_BRACKET) {\n        pos++;\n        depth--;\n        return null;\n      }\n\n      if (str.charCodeAt(pos) !== CHAR_COMMA) {\n        return error(`Expected ',' or ']' in array at position ${pos}`);\n      }\n      pos++; // skip ','\n    }\n  }\n\n  // Main parse\n  const result = parseValue();\n  if (result) return result;\n\n  skipWhitespace();\n\n  if (pos < len) {\n    return error(`Unexpected content after JSON value at position ${pos}`);\n  }\n\n  return { valid: true };\n}\n\n// CLI wrapper (T2): runs when this file is executed directly\nif (import.meta.path === Bun.main) {\n  async function main(): Promise<void> {\n    const filePath = process.argv[2];\n    let input: string;\n\n    if (filePath) {\n      const file = Bun.file(filePath);\n      const exists = await file.exists();\n      if (!exists) {\n        console.log(JSON.stringify({ valid: false, error: `File not found: ${filePath}` }));\n        process.exit(1);\n      }\n      input = await file.text();\n    } else {\n      input = await Bun.stdin.text();\n    }\n\n    const result = validateJson(input);\n    console.log(JSON.stringify(result));\n    process.exit(result.valid ? 0 : 1);\n  }\n\n  main();\n}\n"
