    const entries: string[] = [];
    const targetSize = 1024 * 1024; // 1MB
    let currentSize = 0;
    let index = 0;

    while (currentSize < targetSize) {
      const entry = `"key_${index}":{"value":${index},"name":"item_${index}","active":true,"tags":["a","b","c"]}`;
      entries.push(entry);
      currentSize += entry.length;
      index++;
